insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('fv_pattern', 'fever', 'hopi', 1, 'choice', '[{"v": "continuous", "en": "Continuous (stays high)", "hi": "लगातार बना रहता है", "mr": "सतत राहतो", "ddx": ["Enteric fever", "Pneumonia", "Cystitis / UTI"]}, {"v": "comes_goes", "en": "Comes and goes daily", "hi": "रोज़ चढ़ता-उतरता है", "mr": "रोज चढतो-उतरतो", "ddx": ["Tuberculosis", "Deep abscess"]}, {"v": "alternate", "en": "Comes on alternate days / with gaps", "hi": "एक-दो दिन छोड़कर आता है", "mr": "एक-दोन दिवस सोडून येतो", "ddx": ["Malaria"]}, {"v": "evening", "en": "Mostly evening / night", "hi": "ज़्यादातर शाम या रात को", "mr": "बहुतेक संध्याकाळी / रात्री", "ddx": ["Tuberculosis", "Lymphoma"]}]'::jsonb, 'Pattern of fever', 'बुखार कैसे आता है?', 'ताप कसा येतो?', 'Fever pattern', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 10, p144-145', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
