insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('hm_source', 'haemoptysis', 'hopi', 3, 'choice', '[{"v": "cough", "en": "Comes up with cough, frothy, bright red", "hi": "खाँसी के साथ, झागदार, चमकीला लाल", "mr": "खोकल्यासोबत, फेसाळ, चमकदार लाल", "ddx": ["Tuberculosis", "Lung cancer", "Bronchiectasis"]}, {"v": "vomit", "en": "With vomiting, dark / coffee-coloured", "hi": "उल्टी के साथ, गहरा / कॉफ़ी रंग", "mr": "उलटीसोबत, गडद / कॉफी रंग", "ddx": ["Upper GI bleed (haematemesis)"]}, {"v": "nose_gums", "en": "From nose / gums, then spat out", "hi": "नाक / मसूड़ों से, फिर थूका", "mr": "नाक / हिरड्यांतून, मग थुंकले", "ddx": ["Epistaxis / gum bleeding"]}]'::jsonb, 'Where does the blood seem to come from?', 'खून कहाँ से आता लगता है?', 'रक्त कुठून येते असे वाटते?', 'Source (true haemoptysis vs mimics)', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 12, p169', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
