ive=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('hd_provoke', 'headache', 'hopi', 12, 'multi', '[{"v": "cough_strain", "en": "Coughing / straining / bending", "hi": "खाँसना / ज़ोर लगाना / झुकना", "mr": "खोकणे / जोर लावणे / वाकणे", "ddx": ["Raised intracranial pressure"]}, {"v": "touch_face", "en": "Touching face / chewing / brushing teeth", "hi": "चेहरा छूना / चबाना / ब्रश करना", "mr": "चेहऱ्याला स्पर्श / चावणे / ब्रश करणे", "ddx": ["Trigeminal neuralgia"]}, {"v": "alcohol", "en": "Alcohol", "hi": "शराब", "mr": "दारू", "ddx": ["Cluster headache", "Migraine"]}, {"v": "sleep_food", "en": "Missed meals / poor sleep / periods", "hi": "खाना छूटना / नींद कम / माहवारी", "mr": "जेवण चुकणे / झोप कमी / पाळी", "ddx": ["Migraine"]}, {"v": "exertion_sex", "en": "Exertion / during sex", "hi": "मेहनत / संभोग के समय", "mr": "श्रम / संभोगाच्या वेळी", "ddx": ["Subarachnoid haemorrhage", "Benign exertional headache"]}, {"v": "screen_stress", "en": "Stress / long screen work", "hi": "तनाव / देर तक स्क्रीन", "mr": "ताण / बराच वेळ स्क्रीन", "ddx": ["Tension-type"]}, {"v": "wakes_sleep", "en": "Wakes from sleep with it", "hi": "दर्द से नींद खुल जाती है", "mr": "दुखण्याने झोपेतून जाग येते", "ddx": ["Cluster headache", "Raised intracranial pressure"]}]'::jsonb, 'What brings it on / makes it worse?', 'किससे शुरू होता / बढ़ता है?', 'कशाने सुरू होते / वाढते?', 'Provoking factors', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 16, p311 (Table 16.2)', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
