insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('fi_neutropenic', 'infections', 'redflag', 2, 'yesno', null, 'On chemotherapy / cancer treatment and now has fever?', 'क्या कीमोथेरेपी / कैंसर का इलाज चल रहा और अब बुखार है?', 'केमोथेरपी / कर्करोग उपचार सुरू आहे आणि आता ताप आहे?', 'Fever on chemotherapy', null, null, null, true, 'Possible neutropenic sepsis — EMERGENCY (antibiotics within 1 hour)', null, null, array['Neutropenic sepsis']::text[], 'General clinical practice', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('fi_risk', 'infections', 'risk', 3, 'multi', '[{"v": "dm", "en": "Diabetes", "hi": "शुगर", "mr": "मधुमेह", "ddx": ["Diabetes"]}, {"v": "steroid_immuno", "en": "Steroids / immune-lowering drugs (e.g. for arthritis, transplant)", "hi": "स्टेरॉयड / प्रतिरोधक शक्ति घटाने वाली दवा", "mr": "स्टिरॉइड / प्रतिकारशक्ती कमी करणारी औषधे", "ddx": ["Drug-induced immunosuppression"]}, {"v": "hiv_risk", "en": "HIV risk (unsafe sex, injections, transfusion)", "hi": "एचआईवी का ख़तरा (असुरक्षित संबंध, इंजेक्शन, ख़ून चढ़ा)", "mr": "एचआयव्हीचा धोका (असुरक्षित संबंध, इंजेक्शन, रक्त)", "ddx": ["HIV"]}, {"v": "malnutrition", "en": "Very thin / poor food", "hi": "बहुत दुबला / खाना कम", "mr": "खूप कृश / आहार कमी", "ddx": ["Malnutrition"]}, {"v": "spleen", "en": "Spleen removed", "hi": "तिल्ली निकाली गई", "mr": "प्लीहा काढली", "ddx": ["Post-splenectomy"]}, {"v": "child_recurrent", "en": "(Child) infections since infancy, poor growth", "hi": "(बच्चा) बचपन से इन्फेक्शन, विकास कम", "mr": "(मूल) लहानपणापासून संसर्ग, वाढ कमी", "ddx": ["Primary immunodeficiency"]}]'::jsonb, 'Possible causes of low immunity', 'रोग-प्रतिरोधक शक्ति कम होने के कारण', 'रोगप्रतिकारशक्ती कमी होण्याची कारणे', 'Immunosuppression risk', null, null, null, false, null, null, null, '{}'::text[], 'General clinical practice', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('fi_blood_counts', 'infections', 'associated', 4, 'yesno', null, 'Also pale / easy bruising / bleeding gums?', 'क्या साथ में पीलापन / आसानी से नील / मसूड़ों से ख़ून?', 'सोबत फिकटपणा / सहज काळे-निळे / हिरड्यांतून रक्त?', 'Features of marrow failure', null, null, null, true, 'Infections + anaemia + bleeding — possible leukaemia / marrow failure, urgent CBC', null, null, array['Leukaemia','Aplastic anaemia']::text[], 'General clinical practice', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('rs_severe', 'rash', 'redflag', 1, 'multi', '[{"v": "blisters_peeling", "en": "Blisters / skin peeling off in sheets", "hi": "छाले / त्वचा परतों में उतरना", "mr": "फोड / त्वचा थरांनी निघणे", "ddx": ["Stevens-Johnson / TEN"]}, {"v": "mouth_eyes", "en": "Sores in mouth, eyes or genitals", "hi": "मुँह, आँख या गुप्तांग में छाले", "mr": "तोंड, डोळे किंवा गुप्तांगात फोड", "ddx": ["Stevens-Johnson / TEN"]}, {"v": "swelling_breath", "en": "Lips/face swelling or breathing difficulty", "hi": "होंठ/चेहरा सूजना या साँस में तकलीफ़", "mr": "ओठ/चेहरा सुजणे किंवा श्वासाचा त्रास", "ddx": ["Anaphylaxis / angioedema"]}, {"v": "purple_fever", "en": "Purple spots that don''t fade + fever / drowsy", "hi": "बैंगनी धब्बे जो दबाने पर नहीं मिटते + बुखार / सुस्ती", "mr": "जांभळे डाग जे दाबल्यावर जात नाहीत + ताप / गुंगी", "ddx": ["Meningococcal sepsis", "Dengue"]}, {"v": "whole_body_red", "en": "Whole body red and hot", "hi": "पूरा शरीर लाल और गर्म", "mr": "संपूर्ण अंग लाल व गरम", "ddx": ["Erythroderma"]}]'::jsonb, 'Danger signs with rash', 'दानों के साथ ख़तरे के निशान', 'पुरळासोबत धोक्याची चिन्हे', 'Rash red flags', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 19, p415 (Box 19.11)', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('rs_sjs_flag', 'rash', 'redflag', 2, 'yesno', null, 'Any blisters, peeling, mouth/eye sores, face swelling or purple spots with fever?', 'क्या कोई छाले, त्वचा उतरना, मुँह/आँख में छाले, चेहरे पर सूजन, या बुखार के साथ बैंगनी धब्बे?', 'कोणतेही फोड, त्वचा निघणे, तोंड/डोळ्यात फोड, चेहऱ्यावर सूज, किंवा तापासोबत जांभळे डाग?', 'Dermatological emergency', null, null, null, true, 'Severe skin reaction (SJS/TEN, anaphylaxis, purpura) — EMERGENCY, stop new drug', null, null, array['Stevens-Johnson / TEN','Anaphylaxis / angioedema','Meningococcal sepsis']::text[], 'Hutchison 24e, Ch 19, p415', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('rs_course', 'rash', 'hopi', 3, 'choice', '[{"v": "hours_comes_goes", "en": "Raised itchy welts that come and go within hours", "hi": "उभरे खुजली वाले चकत्ते जो घंटों में आते-जाते", "mr": "उठावदार खाजरे चट्टे जे तासांत येतात-जातात", "ddx": ["Urticaria"]}, {"v": "days_fever", "en": "Spread over a few days with fever", "hi": "बुखार के साथ कुछ दिनों में फैले", "mr": "तापासोबत काही दिवसांत पसरले", "ddx": ["Viral exanthem", "Measles", "Chickenpox", "Dengue", "Drug reaction"]}, {"v": "weeks_months", "en": "Weeks / months, slowly spreading", "hi": "हफ़्तों / महीनों से धीरे-धीरे फैल रहे", "mr": "आठवडे / महिन्यांपासून हळूहळू पसरत", "ddx": ["Eczema", "Psoriasis", "Tinea (ringworm)", "Scabies"]}, {"v": "recurrent_same_spot", "en": "Comes back at the same spot each time (after a tablet)", "hi": "हर बार उसी जगह लौटते (किसी गोली के बाद)", "mr": "प्रत्येक वेळी त्याच जागी परत येतात (गोळीनंतर)", "ddx": ["Fixed drug eruption"]}]'::jsonb, 'How did it start and change?', 'दाने कैसे शुरू हुए और बदले?', 'पुरळ कसे सुरू झाले व बदलले?', 'Time course', null, null, null, false, null, null, null, '{}'::text[], 'Hutchison 24e, Ch 19, p403-405 (Box 19.3)', true) on conflict (id) do update set complaint_id=excluded.complaint_id, section=excluded.section, ord=excluded.ord, qtype=excluded.qtype, options=excluded.options, text_en=excluded.text_en, text_hi=excluded.text_hi, text_mr=excluded.text_mr, clinical_term=excluded.clinical_term, dedupe_key=excluded.dedupe_key, show_if=excluded.show_if, applies_to=excluded.applies_to, red_flag=excluded.red_flag, red_flag_note=excluded.red_flag_note, positive_means=excluded.positive_means, negative_means=excluded.negative_means, differentials=excluded.differentials, source=excluded.source, active=excluded.active, reviewed_on=current_date;
insert into public.hx_questions(id, complaint_id, section, ord, qtype, options, text_en, text_hi, text_mr, clinical_term, dedupe_key, show_if, applies_to, red_flag, red_flag_note, positive_means, negative_means, differentials, source, active) values ('rs_distribution', 'rash', 'hopi', 4, 'multi', '[{"v": "web_wrist_genital", "en": "Finger webs, wrists, waist, genitals", "hi": "उँगलियों के बीच, कलाई, कमर, गुप्तांग", "mr": "बोटांच्या मधे, मनगट, कंबर, गुप्तांग", "ddx": ["Scabies"]}, {"v": "folds_groin", "en": "Groin / under breasts / skin folds", "hi": "जांघ / स्तन के नीचे / त्वचा की सिलवटें", "mr": "जांघ / स्तनाखाली / त्वचेच्या घड्या", "ddx": ["Tinea (ringworm)", "Candida intertrigo"]}, {"v": "elbows_knees_scalp", "en": "Elbows, knees, scalp (scaly)", "hi": "कोहनी, घुटने, सिर (पपड़ी)", "mr": "कोपर, गुडघे, डोके (खपल्या)", "ddx": ["Psoriasis"]}, {"v": "flexures_child", "en": "Inside elbows / behind knees (since childhood)", "hi": "कोहनी के अंदर / घुटने के पीछे (बचपन से)", "mr": "कोपराच्या आत / गुडघ्यामागे (लहानपणापासून)", "ddx": ["Eczema"]}, {"v": "sun_exposed", "en": "Only sun-exposed parts (face, arms)", "hi": "सिर्फ़ धूप वाले हिस्से (चेहरा, हाथ)", "mr": "फक्त उन्हात येणारे भाग (चेहरा, हात)", "ddx": ["Photosensitivity", "SLE", "Pellagra"]}, {"v": "one_band", "en": "A band on one side of body (painful)", "hi": "शरीर के एक तरफ पट्टी (दर्दनाक)", "mr": "शरीराच्या एका बाजूला पट्टा (दुखरा)", "ddx": ["Herpes zoster"]}, {"v": "contact_area", "en": "Only where something touched (watch, cream, chappal)", "hi": "सिर्फ़ जहाँ कुछ छुआ (घड़ी, क्रीम, चप्पल)", "mr": "फक्त जिथे काही स्पर्श झाला (घड्याळ, क्रीम, चप्पल)", "ddx": ["Contact dermatitis"]}, {"v": "palms_soles", "en": "Palms and soles", "hi": "हथेली और तलवे", "mr": "तळहात व तळपाय", "ddx": ["Secondary syphilis", "Hand-foot-mouth disease", "Erythema multiforme"]}, {"v": "shins_painful", "en": "Painful red lumps on shins", "hi": "पिंडली पर दर्दनाक लाल गाँठें", "mr": "नडगीवर दुखऱ्या लाल गाठी", "ddx": ["Erythema nodosum"]}]'::jsonb